uniform float iTime;
uniform vec2 iResolution;
uniform vec4 iMouse;
uniform sampler2D iChannel0;

// Parameter mappings
uniform float u_speed;
uniform float u_scale;
uniform float u_intensity;
uniform float u_color_cycle;
uniform float u_layers;
uniform float u_density;
uniform float u_connection_radius;
uniform float u_pulse_intensity;
uniform float u_color_base;
uniform float u_color_pulse;
uniform float u_neon_glow;
uniform float u_bloom;

out vec4 fragColor;

// --- Helper Functions ---

mat2 rot(float a) {
    float s = sin(a), c = cos(a);
    return mat2(c, -s, s, c);
}

// Pseudo-random hash for data streams
float hash21(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}

// Color conversion
vec3 hsv2rgb(vec3 c) {
    vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
    vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
    return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}

// --- 3D Terrain Distance Function ---
float map(vec3 p, float t, float waveInt) {
    // Generates organic digital mountains and valleys
    float wave = sin(p.x * 0.6 + t * 0.5) * cos(p.z * 0.4 - t * 0.3) * waveInt;
    wave += sin(p.x * 0.2 + p.z * 0.3 + t * 0.2) * (waveInt * 0.8);

    float floorD = p.y + 2.0 - wave; 
    // Ceiling is higher and smoother, creating an immersive data cave
    float ceilD  = 5.0 - p.y - wave * 0.3; 

    return min(floorD, ceilD);
}

void main() {
    vec2 uv = (gl_FragCoord.xy - 0.5 * iResolution.xy) / iResolution.y;

    // Parameter Fallbacks & Scaling
    float spd = (u_speed <= 0.0) ? 1.0 : u_speed * 1.5;
    float t = iTime * spd;

    float scaleBase = (u_scale <= 0.0) ? 1.0 : u_scale * 0.5;
    float waveInt = (u_connection_radius <= 0.0) ? 1.5 : u_connection_radius * 0.4; // Repurposed for terrain height
    float density = (u_density <= 0.0) ? 0.5 : u_density; 

    // Deep blue background, electric cyan pulses (Defaults matched to the video)
    float hueBase = fract((u_color_base <= 0.0 ? 0.6 : u_color_base) + (t * u_color_cycle * 0.05));
    float huePulse = fract((u_color_pulse <= 0.0 ? 0.5 : u_color_pulse) + (t * u_color_cycle * 0.05));

    vec3 baseCol = hsv2rgb(vec3(hueBase, 0.9, 0.8)); 
    vec3 pulseCol = hsv2rgb(vec3(huePulse, 0.6, 1.0)); 

    // --- Raymarching Setup ---
    vec3 ro = vec3(0.0, 0.0, t * 5.0); // Camera flies forward
    vec3 rd = normalize(vec3(uv, 1.0)); // Wide FOV

    // Interactive Camera Pan (Look around with mouse)
    vec2 mouseOffset = (iMouse.z > 0.0) ? (iMouse.xy / iResolution.xy - 0.5) * 2.0 : vec2(0.0, -0.15);
    rd.yz *= rot(mouseOffset.y);
    rd.xz *= rot(mouseOffset.x);

    // Natural camera bank (Drone roll effect)
    rd.xy *= rot(sin(t * 0.3) * 0.15);

    // --- Raymarching Loop ---
    float t_dist = 0.0;
    vec3 p;
    float glow = 0.0;

    for(int i = 0; i < 90; i++) {
        p = ro + rd * t_dist;
        float d = map(p, t, waveInt);

        // Accumulate volumetric neon fog in the empty space
        glow += exp(-d * 8.0) * 0.02;

        if(d < 0.01 || t_dist > 50.0) break;
        t_dist += d * 0.6; // Safe stepping for wavy terrain
    }

    vec3 finalColor = vec3(0.0);

    // --- Grid Surface Rendering ---
    if(t_dist < 50.0) {
        vec2 gridUV = p.xz * scaleBase;
        vec2 gridId = floor(gridUV);
        vec2 f = abs(fract(gridUV) - 0.5);

        // Analytical Anti-Aliasing (Lines get slightly thicker in the distance to prevent noise)
        float thick = 0.02 + t_dist * 0.002; 

        // Base Structural Grid
        float lineX = smoothstep(thick, thick * 0.1, f.x);
        float lineY = smoothstep(thick, thick * 0.1, f.y);
        float grid = max(lineX, lineY);

        // Nodes (Intersections)
        float node = smoothstep(thick * 3.0, thick * 0.5, length(f));

        // --- Cyber Data Streams ---
        // Z-Axis Streams (Running forward/backward)
        float speedZ = hash21(vec2(gridId.x, 1.0)) * 8.0 + 2.0;
        float pulseZ = smoothstep(0.85, 1.0, sin(gridUV.y * 1.5 + t * speedZ));

        // X-Axis Streams (Running left/right)
        float speedX = hash21(vec2(1.0, gridId.y)) * 8.0 + 2.0;
        float pulseX = smoothstep(0.85, 1.0, sin(gridUV.x * 1.5 - t * speedX));

        // Density fader controls how many lines are actively transmitting data
        float streamMaskZ = step(1.0 - density, hash21(vec2(gridId.x, 2.0)));
        float streamMaskX = step(1.0 - density, hash21(vec2(gridId.y, 2.0)));

        float dataPulse = (pulseZ * lineX * streamMaskZ) + (pulseX * lineY * streamMaskX);

        // --- Layer Coloring ---
        float intensity = (u_intensity <= 0.0 ? 1.5 : u_intensity);
        float pulseInt = (u_pulse_intensity <= 0.0 ? 2.0 : u_pulse_intensity * 3.0);

        vec3 baseGridCol = baseCol * grid * 0.3 * intensity;
        vec3 nodeCol = pulseCol * node * 0.8 * intensity;
        vec3 dataCol = pulseCol * dataPulse * pulseInt;

        finalColor = baseGridCol + nodeCol + dataCol;

        // Depth Fog (Fades the grid smoothly into the void)
        float fog = exp(-t_dist * 0.08);
        finalColor *= fog;
    }

    // --- Atmosphere & Post-Processing ---
    float neonSlider = (u_neon_glow <= 0.0 ? 1.0 : u_neon_glow);
    float bloomSlider = (u_bloom <= 0.0 ? 1.0 : u_bloom);

    // Add Volumetric Ambient Haze
    finalColor += pulseCol * glow * neonSlider * 0.4;

    // Distant Bloom / Digital Horizon
    finalColor += baseCol * bloomSlider * exp(-t_dist * 0.04);

    // Smooth Vignette
    float vig = smoothstep(1.3, 0.2, length(uv));
    finalColor *= vig;

    // Cinematic Contrast Curve
    finalColor = pow(finalColor, vec3(0.85));

    fragColor = vec4(finalColor, 1.0);
}
